import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input sanitizer - strips common attack chars but allows quotes for names
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove null bytes and control characters
        input = input.replaceAll("[\\x00-\\x1f]", "");
        // Collapse multiple spaces
        input = input.replaceAll("\\s+", " ").trim();
        // Length limit
        if (input.length() > 200) input = input.substring(0, 200);
        return input;
    }

    // Validates department format - must be alphanumeric with optional hyphens
    private boolean isValidDepartment(String dept) {
        return dept != null && Pattern.matches("^[A-Za-z0-9][A-Za-z0-9\\-]{0,49}$", dept);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String department = req.getParameter("dept");
        String quarter = req.getParameter("quarter");
        String sortCol = req.getParameter("sort");

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        if (!isValidDepartment(department)) {
            resp.setStatus(400);
            out.write("{\"error\": \"Invalid department format\"}");
            return;
        }

        // Quarter validation - must match pattern like Q1-2024
        if (quarter == null || !Pattern.matches("^Q[1-4]-\\d{4}$", quarter)) {
            resp.setStatus(400);
            out.write("{\"error\": \"Invalid quarter format\"}");
            return;
        }

        // Sort column - apply sanitizer but allow flexibility for column names
        sortCol = sanitizeInput(sortCol);
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "employee_name";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Department and quarter use parameterized query
            // Sort column is validated through sanitizer above
            String sql = "SELECT employee_name, role, salary, bonus FROM compensation "
                       + "WHERE department = ? AND quarter = ? "
                       + "ORDER BY " + sortCol;

            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, department);
            stmt.setString(2, quarter);

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"name\": \"").append(rs.getString("employee_name")).append("\", ");
                json.append("\"role\": \"").append(rs.getString("role")).append("\", ");
                json.append("\"salary\": ").append(rs.getInt("salary")).append(", ");
                json.append("\"bonus\": ").append(rs.getInt("bonus"));
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.write(json.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            out.write("{\"error\": \"Database error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(405);
        resp.getWriter().write("{\"error\": \"Method not allowed\"}");
    }
}
